package org.eclipse.rdf4j.sail.lmdb.csf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.Random;

import org.eclipse.rdf4j.sail.lmdb.csf.CsfGenerationRowLookupAccelerators.Index;
import org.eclipse.rdf4j.sail.lmdb.csf.CsfGenerationRowLookupAccelerators.Kind;
import org.eclipse.rdf4j.sail.lmdb.csf.CsfGenerationRowLookupAccelerators.MinimalPerfectHashIndex;
import org.junit.jupiter.api.Test;

class CsfGenerationRowLookupAcceleratorsTest {

	@Test
	void exactDictionariesMatchUnsignedBinarySearch() {
		Random random = new Random(0x4745_4e44_4952_4543L);
		for (int size : new int[] { 0, 1, 2, 7, 64, 257, 1_024, 4_096 }) {
			for (int round = 0; round < 8; round++) {
				long[] rows = randomRows(random, size);
				long[] references = references(size);
				for (Kind kind : Kind.values()) {
					Index index = CsfGenerationRowLookupAccelerators.build(kind, rows, references, size);
					for (int ordinal = 0; ordinal < size; ordinal++) {
						assertEquals(references[ordinal], index.find(rows[ordinal]), kind.name());
					}
					for (int miss = 0; miss < 4_096; miss++) {
						long target = random.nextLong();
						int expected = CsfRowLookupAccelerators.binarySearchUnsigned(rows, 0, size - 1, target);
						assertEquals(expected < 0 ? 0 : references[expected], index.find(target), kind.name());
					}
				}
			}
		}
	}

	@Test
	void minimalPerfectHashUsesExactlyOneKeyAndReferenceSlotPerRow() {
		long[] rows = randomRows(new Random(17), 1_024);
		long[] references = references(rows.length);
		MinimalPerfectHashIndex index = (MinimalPerfectHashIndex) CsfGenerationRowLookupAccelerators.build(
				Kind.MINIMAL_PERFECT_HASH, rows, references, rows.length);
		assertEquals(1, index.worstCaseCandidates());
		assertTrue(index.auxiliaryBytes() >= (long) rows.length * 2L * Long.BYTES);
		assertTrue(index.buildAttempts() >= 1 && index.buildAttempts() <= 64);
		assertTrue(index.worstBucket() >= 1);
	}

	@Test
	void handlesUnsignedSignedBoundary() {
		long[] rows = {
				Long.MAX_VALUE - 1,
				Long.MAX_VALUE,
				Long.MIN_VALUE,
				Long.MIN_VALUE + 1,
				-2L,
				-1L
		};
		long[] references = references(rows.length);
		for (Kind kind : Kind.values()) {
			Index index = CsfGenerationRowLookupAccelerators.build(kind, rows, references, rows.length);
			for (int i = 0; i < rows.length; i++) {
				assertEquals(references[i], index.find(rows[i]), kind.name());
			}
			assertEquals(0, index.find(0), kind.name());
			assertEquals(0, index.find(Long.MIN_VALUE + 2), kind.name());
		}
	}

	@Test
	void rejectsInvalidRowsAndReferences() {
		for (Kind kind : Kind.values()) {
			assertThrows(IllegalArgumentException.class,
					() -> CsfGenerationRowLookupAccelerators.build(kind, new long[] { 2, 1 },
							new long[] { 1, 2 }, 2),
					kind.name());
			assertThrows(IllegalArgumentException.class,
					() -> CsfGenerationRowLookupAccelerators.build(kind, new long[] { 1, 1 },
							new long[] { 1, 2 }, 2),
					kind.name());
			assertThrows(IllegalArgumentException.class,
					() -> CsfGenerationRowLookupAccelerators.build(kind, new long[] { 1, 2 },
							new long[] { 1, 0 }, 2),
					kind.name());
		}
	}

	private static long[] references(int size) {
		long[] references = new long[size];
		for (int i = 0; i < size; i++) {
			references[i] = 1L + ((long) i << 10);
		}
		return references;
	}

	private static long[] randomRows(Random random, int size) {
		long[] rows = new long[size];
		for (int i = 0; i < size; i++) {
			long candidate;
			do {
				candidate = random.nextLong();
			} while (contains(rows, i, candidate));
			rows[i] = candidate;
		}
		for (int i = 0; i < rows.length; i++) {
			rows[i] ^= Long.MIN_VALUE;
		}
		Arrays.sort(rows);
		for (int i = 0; i < rows.length; i++) {
			rows[i] ^= Long.MIN_VALUE;
		}
		return rows;
	}

	private static boolean contains(long[] rows, int length, long target) {
		for (int i = 0; i < length; i++) {
			if (rows[i] == target) {
				return true;
			}
		}
		return false;
	}
}
